import { createAsyncThunk } from '@reduxjs/toolkit';
import { FilterRegistry } from 'domain/Filter';
import type { FilterForm, FiltersState, FilterValue } from 'models/Filters';
import { updateFormValue } from 'redux/slices/filters/filters';
import { refreshCommercialResultsFilterData } from 'redux/slices/filters/thunk/filtersThunk';
import type { AppDispatch } from 'redux/types';

import { resolveCommercialResultsRefreshTier } from './commercialResultsRefreshMeta';
import { COMMERCIAL_RESULTS_PAGE_NAME } from './constants';

/** Filters sent by Watch Tower → Commercial Results deep links. */
const COMMERCIAL_URL_FILTER_KEYS = [
  'zone',
  'country',
  'periods',
  'brands',
  'kpis',
  'brand_filter_groupings',
] as const;

export function extractCommercialUrlFilters(
  searchParams: URLSearchParams,
): Partial<FilterForm> {
  const fromUrl = FilterRegistry.extractFiltersFromUrl(searchParams);
  const allowed = new Set<string>(COMMERCIAL_URL_FILTER_KEYS);

  return Object.entries(fromUrl).reduce<Partial<FilterForm>>(
    (acc, [key, value]) => {
      if (!allowed.has(key) || value == null || value === '') return acc;
      acc[key] = value;
      return acc;
    },
    {},
  );
}

function isSpecificBrand(brand: FilterValue | undefined): boolean {
  if (brand == null || brand === '') return false;
  return String(brand).toUpperCase() !== 'ALL';
}

function hasConcreteCountry(filters: Partial<FilterForm>): boolean {
  const country = filters.country;
  if (country == null || country === '') return false;
  return String(country).toUpperCase() !== 'ABI';
}

function needsSequentialBrandPresetStep(
  urlFilters: Partial<FilterForm>,
): boolean {
  return hasConcreteCountry(urlFilters) && isSpecificBrand(urlFilters.brands);
}

function omitBrand(filters: Partial<FilterForm>): Partial<FilterForm> {
  const { brands: _brands, ...rest } = filters;
  return rest;
}

function applyUrlFiltersToForm(
  dispatch: AppDispatch,
  filters: Partial<FilterForm>,
): void {
  const orderedKeys = FilterRegistry.getInstance().getOrderedKeys();

  orderedKeys.forEach((key) => {
    if (key in filters) {
      dispatch(
        updateFormValue({
          key,
          value: filters[key as keyof FilterForm] as FilterValue,
        }),
      );
    }
  });
}

function resolveFinalPresetTrigger(
  urlFilters: Partial<FilterForm>,
): string | undefined {
  const tier = resolveCommercialResultsRefreshTier(urlFilters as FilterForm);
  if (tier === 3) return 'brands';
  if (tier === 2) return 'country';
  if (urlFilters.zone != null && urlFilters.zone !== '') return 'zone';
  return undefined;
}

/**
 * Tiered Commercial Results URL sync: waits for each preset refresh to finish
 * before advancing (country catalog → brand selection).
 */
export const syncCommercialResultsFiltersFromUrl = createAsyncThunk<
  void,
  URLSearchParams,
  { state: { filters: FiltersState }; dispatch: AppDispatch }
>(
  'filters/syncCommercialResultsFiltersFromUrl',
  async (searchParams, { dispatch }) => {
    const urlFilters = extractCommercialUrlFilters(searchParams);
    if (Object.keys(urlFilters).length === 0) return;

    const targetBrand = urlFilters.brands;
    const sequentialBrandStep = needsSequentialBrandPresetStep(urlFilters);
    const initialFilters = sequentialBrandStep
      ? omitBrand(urlFilters)
      : urlFilters;

    applyUrlFiltersToForm(dispatch, initialFilters);

    if (sequentialBrandStep) {
      await dispatch(
        refreshCommercialResultsFilterData({
          scope: 'form',
          triggerField: 'country',
        }),
      ).unwrap();

      dispatch(
        updateFormValue({
          key: 'brands',
          value: targetBrand as FilterValue,
        }),
      );

      await dispatch(
        refreshCommercialResultsFilterData({
          scope: 'form',
          triggerField: 'brands',
          urlNavigationCommit: true,
        }),
      ).unwrap();

      return;
    }

    await dispatch(
      refreshCommercialResultsFilterData({
        scope: 'form',
        triggerField: resolveFinalPresetTrigger(urlFilters),
        urlNavigationCommit: true,
      }),
    ).unwrap();
  },
  {
    condition: (_, { getState }) => {
      const page = getState().filters?.pages?.[COMMERCIAL_RESULTS_PAGE_NAME];
      return page?.status === 'loaded';
    },
  },
);
